{"path":"index.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>{{BUSINESS_NAME}} — Sound Baths & Restorative Sound</title>
  <meta name='description' content='Sensory, premium sound bath experiences and private sessions in {{CITY}}, {{STATE}}.'>
  <link rel='stylesheet' href='assets/css/styles.css'>
  <script src='assets/js/main.js' defer></script>
</head>
<body class='site'>
  <header class='site-header'>
    <div class='wrap'>
      <a class='brand' href='index.html' aria-label='{{BUSINESS_NAME}} home'>
        <svg class='logo' viewBox='0 0 100 24' role='img' aria-hidden='true'>
          <defs>
            <linearGradient id='g1' x1='0' x2='1'>
              <stop offset='0' stop-color='#8bd3c7'/>
              <stop offset='1' stop-color='#6c5ce7'/>
            </linearGradient>
          </defs>
          <rect x='0' y='0' width='100' height='24' rx='4' fill='url(#g1)' opacity='0.12'></rect>
          <text x='12' y='16' fill='#2b2b2b' font-size='10' font-family='system-ui, -apple-system, sans-serif'>{{BUSINESS_NAME}}</text>
        </svg>
      </a>
      <nav class='nav' aria-label='Primary'>
        <a href='events.html'>Gatherings</a>
        <a href='private-sessions.html'>Sessions</a>
        <a href='pricing.html'>Rates</a>
        <a href='about.html'>Our Story</a>
        <a href='faq.html'>FAQ</a>
        <a class='cta' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class='nav-toggle' aria-label='Toggle menu'></button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section id='hero' class='hero' style='background-image: linear-gradient(180deg, rgba(108,92,231,0.06), rgba(139,211,199,0.02)), url("assets/img/pattern.svg");'>
      <div class='wrap hero-inner'>
        <div class='hero-content'>
          <h1 class='eyebrow'>Soothing sessions in {{CITY}}</h1>
          <h2 class='headline'>{{BUSINESS_NAME}} — a premium sensory sound bath</h2>
          <p class='sub'>A modern ritual that blends therapeutic intention, curated instruments, and spacious design to guide you into restful integration. {{TAGLINE}}</p>
          <div class='hero-actions'>
            <a class='btn primary' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
            <a class='btn ghost' href='events.html'>Next Event — {{NEXT_EVENT_DATE}}</a>
          </div>
        </div>
        <div class='hero-visual' aria-hidden='true'>
          <svg class='vibes' viewBox='0 0 200 200'>
            <defs>
              <radialGradient id='rg' cx='50%' cy='50%' r='50%'>
                <stop offset='0' stop-color='#fff' stop-opacity='0.45'/>
                <stop offset='1' stop-color='#6c5ce7' stop-opacity='0'/>
              </radialGradient>
            </defs>
            <circle cx='100' cy='100' r='84' fill='url(#rg)'></circle>
            <g class='ripples' stroke='rgba(108,92,231,0.18)' stroke-width='1.5' fill='none'>
              <circle cx='100' cy='100' r='44'></circle>
              <circle cx='100' cy='100' r='68'></circle>
            </g>
          </svg>
        </div>
      </div>
      <div class='ripple-layer' aria-hidden='true'></div>
    </section>

    <!-- MYTH VS TRUTH -->
    <section id='myth-vs-truth' class='panel invert'>
      <div class='wrap'>
        <h3 class='section-title'>Myths, and the quieter truths</h3>
        <div class='m-vs-t'>
          <article class='card myth'>
            <h4>Myth</h4>
            <p>Sound baths are just music for sleeping.</p>
          </article>
          <article class='card truth'>
            <h4>Truth</h4>
            <p>They are guided, intention-rich practices — sensory journeys that balance nervous system activation and facilitate somatic processing.</p>
          </article>
          <article class='card myth'>
            <h4>Myth</h4>
            <p>Anyone can sit quietly and get the same effect.</p>
          </article>
          <article class='card truth'>
            <h4>Truth</h4>
            <p>Our offerings combine space design, breath cues, and specific instruments (crystal bowls, tuning forks, monochord) to shape the experience for deeper integration.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- PILLARS -->
    <section id='pillars' class='panel'>
      <div class='wrap narrow'>
        <h3 class='section-title'>Three pillars of our work</h3>
        <div class='grid pillars-grid'>
          <div class='pillar'>
            <svg class='icon' viewBox='0 0 24 24' aria-hidden='true'><circle cx='12' cy='12' r='10' fill='#8bd3c7' /></svg>
            <h4>Sensory Craft</h4>
            <p>We design soundscapes with intention: timbre, frequency, and silence woven to support relaxation and nervous system regulation.</p>
          </div>
          <div class='pillar'>
            <svg class='icon' viewBox='0 0 24 24' aria-hidden='true'><rect x='4' y='4' width='16' height='16' rx='3' fill='#6c5ce7' /></svg>
            <h4>Clinical Comfort</h4>
            <p>Rooms are curated for accessibility, warmth, and low sensory overwhelm; we include contraindications and clinical considerations with every booking.</p>
          </div>
          <div class='pillar'>
            <svg class='icon' viewBox='0 0 24 24' aria-hidden='true'><path d='M12 2 L22 6 L12 10 L2 6 Z' fill='#ffe29a' /></svg>
            <h4>Intent-Led Flow</h4>
            <p>Arrival, grounding, the sound journey, and integration — four clear phases that hold space for individual processing.</p>
          </div>
        </div>

        <div class='what-to-bring'>
          <h4>What to bring</h4>
          <ul>
            <li>A yoga mat or blanket and extra layers for warmth</li>
            <li>Eye covering or scarf, water bottle, any personal comfort item</li>
            <li>Optional: journal for integration notes</li>
          </ul>
        </div>

        <div class='contra'>
          <h4>Contraindications</h4>
          <p>Please inform us if you are pregnant, have epilepsy, pacemaker/implanted devices, acute injury, or are currently under psychiatric crisis. Sound can be intense; we provide modifications and alternative placements.</p>
        </div>

        <div class='flow'>
          <h4>Typical flow</h4>
          <ol>
            <li>Arrival & grounding: gentle breathing and intention setting</li>
            <li>Settling: supported lying/seat, props provided</li>
            <li>Sound journey: layered instruments — crystal bowls, chimes, monospheric tones, tuning forks — held with pacing and silence</li>
            <li>Integration: gentle return, short reflection, and tea before departure</li>
          </ol>
        </div>
      </div>
    </section>

    <!-- CASE NOTES -->
    <section id='case-notes' class='panel soft'>
      <div class='wrap narrow'>
        <h3 class='section-title'>Case notes & reflections</h3>
        <div class='testimonials'>
          <blockquote>
            "I left with a palpable shift — less reactivity, and a longer breath. The instruments felt precise and kind." — L.
          </blockquote>
          <blockquote>
            "The facilitator, {{FACILITATOR_NAME}}, moved the group through a structured flow; I appreciated the clinical attention and warmth." — S.
          </blockquote>
        </div>
        <div class='note'>
          <p>We keep short, anonymized session notes to refine pacing and instrumentation for returning attendees.</p>
        </div>
      </div>
    </section>

    <!-- FAQ -->
    <section id='faq' class='panel faq-panel'>
      <div class='wrap narrow'>
        <h3 class='section-title'>Questions we often get</h3>
        <details>
          <summary>How long is a typical group sound bath?</summary>
          <div class='answer'>Most gatherings run 75–90 minutes including arrival and integration. Plan to arrive 10–15 minutes early.</div>
        </details>
        <details>
          <summary>What should I bring?</summary>
          <div class='answer'>See above, but in short: layers, a blanket, an eye covering, water, and anything that helps you feel held.</div>
        </details>
        <details>
          <summary>Are there medical contraindications?</summary>
          <div class='answer'>Yes. Let us know about pregnancy, epilepsy, implanted stimulators, recent head injury, or psychiatric crisis. We will offer modifications or advise alternatives.</div>
        </details>
        <details>
          <summary>Can I book a private session?</summary>
          <div class='answer'>Yes — 1:1, couples, and corporate sound offerings are available on the Sessions page.</div>
        </details>
      </div>
    </section>

    <!-- CTA -->
    <section id='final-cta' class='panel cta-panel'>
      <div class='wrap cta-wrap'>
        <h3>Reserve your place</h3>
        <p>Join {{VENUE_NAME}} in a lit, comfortable room for an intentional sound practice led by {{FACILITATOR_NAME}}. Small groups. Careful attention to setup and safety.</p>
        <div class='cta-actions'>
          <a class='btn primary large' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
          <a class='btn ghost' href='contact.html'>Contact: {{EMAIL}}</a>
        </div>
      </div>
    </section>

  </main>

  <footer class='site-footer'>
    <div class='wrap small'>
      <div class='foot-left'>
        <p>{{BUSINESS_NAME}} • {{CITY}}, {{STATE}}</p>
        <p>Phone: <a href='tel:{{PHONE}}'>{{PHONE}}</a> • <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></p>
      </div>
      <div class='foot-right'>
        <nav class='footer-nav'>
          <a href='events.html'>Events</a>
          <a href='about.html'>About</a>
          <a href='book.html'>Book</a>
        </nav>
        <p class='smallprint'>© {{BUSINESS_NAME}} — curated sound experiences. Not a substitute for medical advice.</p>
      </div>
    </div>
  </footer>
</body>
</html>"} 
