{"path":"assets/css/styles.css","content":"/* Base styles for mystic_modern, clinic_modern layout */
:root{
  --bg:#fbfbfe;
  --muted:#6b6b78;
  --accent:#6c5ce7;
  --accent-2:#8bd3c7;
  --card:#ffffff;
  --glass: rgba(255,255,255,0.6);
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#222;background:var(--bg)}
.wrap{max-width:1100px;margin:0 auto;padding:20px}
.wrap.narrow{max-width:880px}
.wrap.small{max-width:980px}
.header,.site-header{position:sticky;top:0;z-index:40;background:linear-gradient(180deg,rgba(255,255,255,0.8),rgba(255,255,255,0.6));backdrop-filter:blur(6px);border-bottom:1px solid rgba(20,20,30,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:18px}
.brand{display:flex;align-items:center;text-decoration:none}
.logo{height:36px;width:auto}
.nav{margin-left:auto;display:flex;gap:14px;align-items:center}
.nav a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:8px}
.nav a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff}
.nav-toggle{display:none}

.hero{padding:60px 0 40px;background-size:400px;background-repeat:repeat;position:relative;overflow:hidden}
.hero-inner{display:flex;gap:36px;align-items:center}
.hero-content{flex:1}
.hero-visual{width:260px;opacity:0.94}
.eyebrow{margin:0;color:var(--accent-2);font-weight:600}
.headline{margin:8px 0 12px;font-size:28px;line-height:1.05}
.sub{margin:0 0 18px;color:var(--muted)}
.hero-actions{display:flex;gap:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff}
.btn.ghost{background:transparent;border:1px solid rgba(20,20,30,0.06);color:var(--muted)}
.btn.large{padding:14px 20px;border-radius:12px}

.panel{padding:48px 0;border-top:1px solid rgba(20,20,30,0.03)}
.panel.invert{background:linear-gradient(180deg,rgba(108,92,231,0.03),transparent)}
.section-title{margin:0 0 18px;font-size:18px;color:#222}
.m-vs-t{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px}
.card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(30,30,40,0.04)}
.card.myth{opacity:0.9}
.card.truth{border-left:3px solid var(--accent-2)}

.pillars-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:18px 0}
.pillar{background:linear-gradient(180deg,var(--glass),rgba(255,255,255,0.9));padding:18px;border-radius:12px}
.pillar .icon{height:46px;width:auto}
.what-to-bring, .contra, .flow{margin-top:18px;padding:14px;border-radius:10px;background:rgba(250,250,255,0.7)}
.what-to-bring ul{margin:8px 0 0;padding-left:18px}
.flow ol{padding-left:18px}

.testimonials blockquote{background:linear-gradient(90deg,rgba(139,211,199,0.06),rgba(108,92,231,0.03));padding:14px;border-left:4px solid var(--accent);margin:12px 0;border-radius:8px}

.faq-panel details{margin:8px 0;padding:12px;border-radius:8px;background:#fff}
.faq-panel summary{cursor:pointer;font-weight:600}

.cta-panel{background:linear-gradient(180deg,rgba(108,92,231,0.04),rgba(139,211,199,0.02));text-align:center;padding:44px 0}
.cta-wrap{display:flex;flex-direction:column;align-items:center;gap:14px}
.cta-actions{display:flex;gap:12px}

.site-footer{padding:26px 0;border-top:1px solid rgba(20,20,30,0.04);background:transparent}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center}
.footer-nav a{margin-right:10px;color:var(--muted);text-decoration:none}
.smallprint{font-size:12px;color:var(--muted);margin:6px 0 0}

/* Responsive */
@media (max-width:880px){
  .hero-inner{flex-direction:column;align-items:flex-start}
  .pillars-grid{grid-template-columns:1fr}
  .nav{display:none}
  .nav-toggle{display:block;margin-left:auto;background:none;border:0;padding:8px}
}

/* Ripple layer for lightweight interactive flourish */
.ripple-layer{position:absolute;inset:0;pointer-events:none}
.ripple-layer .ripple{position:absolute;border-radius:50%;transform:scale(0);opacity:0.36;background:radial-gradient(circle at center, rgba(108,92,231,0.22), rgba(139,211,199,0.02));animation:ripple 1.2s ease-out}
@keyframes ripple{to{transform:scale(6);opacity:0}}

/* Use svg pattern as subtle texture */
body{background-image:url('assets/img/pattern.svg');background-repeat:repeat;background-size:320px;opacity:1}

/* Accessibility */
.sr-only{position:absolute;left:-9999px}
"}
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav toggle
  var btn = document.querySelector('.nav-toggle');
  var nav = document.querySelector('.nav');
  btn && btn.addEventListener('click', function(){
    if(nav.style.display === 'flex'){
      nav.style.display = '';
    } else {
      nav.style.display = 'flex';
      nav.style.flexDirection = 'column';
      nav.style.background = 'rgba(255,255,255,0.98)';
      nav.style.position = 'absolute';
      nav.style.right = '20px';
      nav.style.top = '64px';
      nav.style.padding = '12px';
      nav.style.borderRadius = '12px';
      nav.style.boxShadow = '0 10px 30px rgba(30,30,40,0.06)';
    }
  });

  // Ripple effect on hero click for sensory flourish
  var hero = document.getElementById('hero');
  hero && hero.addEventListener('click', function(e){
    var layer = document.querySelector('.ripple-layer');
    if(!layer) return;
    var ripple = document.createElement('div');
    ripple.className = 'ripple';
    var rect = hero.getBoundingClientRect();
    var x = e.clientX - rect.left;
    var y = e.clientY - rect.top;
    ripple.style.left = (x - 10) + 'px';
    ripple.style.top = (y - 10) + 'px';
    ripple.style.width = '20px';
    ripple.style.height = '20px';
    layer.appendChild(ripple);
    setTimeout(function(){ ripple.remove(); }, 1400);
  });

  // Simple focus reveal for accessibility
  var focusables = document.querySelectorAll('a,button,summary');
  focusables.forEach(function(el){
    el.addEventListener('focus', function(){ el.classList.add('focus-visible'); });
    el.addEventListener('blur', function(){ el.classList.remove('focus-visible'); });
  });
})();"} 
